/* Generated by scripts/build_static.py. App files only; plant data stays in IndexedDB. */
const CACHE = 'plantit-shell-__VERSION__';
const ASSETS = __ASSETS__;
const ROOT = new URL('./', self.location.href);
const URLS = ASSETS.map(path => new URL(path, ROOT).href);
self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(URLS.map(url => new Request(url, { cache: 'reload' })))));
});
self.addEventListener('message', event => {
  if (event.data?.type === 'ACTIVATE_UPDATE') self.skipWaiting();
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('plantit-shell-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});
self.addEventListener('fetch', event => {
  const url = new URL(event.request.url);
  if (event.request.method !== 'GET' || url.origin !== ROOT.origin || !url.pathname.startsWith(ROOT.pathname)) return;
  // Do not cache arbitrary responses or use an HTML fallback for scripts.
  const asset = event.request.mode === 'navigate' ? new URL('index.html', ROOT).href : url.href;
  if (!URLS.includes(asset)) return;
  event.respondWith(caches.open(CACHE).then(async cache => (await cache.match(asset)) || fetch(event.request)));
});
